import React, { useState, useEffect } from 'react';

const StockDetails = ({ symbol }) => {
    const [stockInfo, setStockInfo] = useState(null);
    const [loading, setLoading] = useState(true);
    const [price, setPrice] = useState(null);
    const [change, setChange] = useState(null);
    const [changePercent, setChangePercent] = useState(null);
    const [prevClose, setPrevClose] = useState(null);

    useEffect(() => {
        if (symbol) {
            fetchStockDetails();
            fetchPrice();
            const interval = setInterval(fetchPrice, 30000);
            return () => clearInterval(interval);
        }
    }, [symbol]);

    const fetchStockDetails = async () => {
        setLoading(true);
        try {
            const response = await fetch(`http://localhost:5000/api/stock-info/${symbol}`);
            const data = await response.json();
            if (data && !data.error) {
                setStockInfo(data);
            } else {
                setStockInfo({
                    symbol: symbol,
                    name: symbol,
                    sector: 'N/A',
                    industry: 'N/A',
                    market_cap: 0,
                    pe_ratio: null,
                    dividend_yield: null,
                    eps: null
                });
            }
        } catch (error) {
            console.error('Error fetching stock info:', error);
            setStockInfo({
                symbol: symbol,
                name: symbol,
                sector: 'N/A',
                industry: 'N/A',
                market_cap: 0,
                pe_ratio: null,
                dividend_yield: null,
                eps: null
            });
        }
        setLoading(false);
    };

    const fetchPrice = async () => {
        try {
            const response = await fetch(`http://localhost:5000/api/price/${symbol}`);
            const data = await response.json();
            if (data.price) {
                setPrice(data.price);
                fetchPrevClose();
            }
        } catch (error) {
            console.error('Error fetching price:', error);
        }
    };

    const fetchPrevClose = async () => {
        try {
            const response = await fetch(`http://localhost:5000/api/historical/${symbol}?period=2d&interval=1d`);
            const data = await response.json();
            if (data && data.length >= 2) {
                const prevClosePrice = data[data.length - 2].close;
                setPrevClose(prevClosePrice);
                const currentPrice = price;
                if (currentPrice && prevClosePrice) {
                    const diff = currentPrice - prevClosePrice;
                    const percent = (diff / prevClosePrice) * 100;
                    setChange(diff);
                    setChangePercent(percent);
                }
            }
        } catch (error) {
            console.error('Error fetching previous close:', error);
        }
    };

    if (loading) {
        return (
            <div style={{
                background: '#141b2b',
                padding: '20px',
                borderRadius: '10px',
                border: '1px solid #2a3a5c',
                marginBottom: '20px',
                textAlign: 'center',
                color: '#8a9bb5'
            }}>
                Loading stock details...
            </div>
        );
    }

    return (
        <div style={{
            background: '#141b2b',
            padding: '20px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c',
            marginBottom: '20px'
        }}>
            <div style={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                flexWrap: 'wrap',
                gap: '10px'
            }}>
                <div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <h2 style={{ color: '#e0e6ed', margin: 0 }}>{stockInfo.symbol}</h2>
                        <span style={{
                            fontSize: '11px',
                            background: '#1a2332',
                            padding: '2px 8px',
                            borderRadius: '10px',
                            color: '#8a9bb5'
                        }}>NSE</span>
                        <span style={{
                            fontSize: '11px',
                            background: '#1a2332',
                            padding: '2px 8px',
                            borderRadius: '10px',
                            color: '#8a9bb5'
                        }}>BSE</span>
                    </div>
                    <div style={{ color: '#8a9bb5', fontSize: '16px' }}>
                        {stockInfo.name || stockInfo.symbol}
                    </div>
                    <div style={{ color: '#8a9bb5', fontSize: '14px', marginTop: '4px' }}>
                        {stockInfo.sector} · {stockInfo.industry}
                    </div>
                </div>
                <div style={{ textAlign: 'right' }}>
                    {price ? (
                        <>
                            <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#e0e6ed' }}>
                                ₹{price.toFixed(2)}
                            </div>
                            {change !== null && (
                                <div style={{
                                    fontSize: '18px',
                                    fontWeight: 'bold',
                                    color: change >= 0 ? '#4CAF50' : '#dc3545'
                                }}>
                                    {change >= 0 ? '+' : ''}{change.toFixed(2)} 
                                    ({changePercent !== null ? (changePercent >= 0 ? '+' : '') + changePercent.toFixed(2) : '0.00'}%) 1D
                                </div>
                            )}
                        </>
                    ) : (
                        <div style={{ color: '#8a9bb5' }}>Price unavailable</div>
                    )}
                </div>
            </div>
            <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))',
                gap: '10px',
                marginTop: '15px',
                paddingTop: '15px',
                borderTop: '1px solid #2a3a5c'
            }}>
                <div>
                    <div style={{ color: '#8a9bb5', fontSize: '12px' }}>Market Cap</div>
                    <div style={{ color: '#e0e6ed', fontSize: '14px', fontWeight: 'bold' }}>
                        {stockInfo.market_cap ? `₹${(stockInfo.market_cap / 10000000).toFixed(2)} Cr` : 'N/A'}
                    </div>
                </div>
                <div>
                    <div style={{ color: '#8a9bb5', fontSize: '12px' }}>P/E Ratio</div>
                    <div style={{ color: '#e0e6ed', fontSize: '14px', fontWeight: 'bold' }}>
                        {stockInfo.pe_ratio ? stockInfo.pe_ratio.toFixed(2) : 'N/A'}
                    </div>
                </div>
                <div>
                    <div style={{ color: '#8a9bb5', fontSize: '12px' }}>Dividend Yield</div>
                    <div style={{ color: '#e0e6ed', fontSize: '14px', fontWeight: 'bold' }}>
                        {stockInfo.dividend_yield ? (stockInfo.dividend_yield * 100).toFixed(2) : 'N/A'}%
                    </div>
                </div>
                <div>
                    <div style={{ color: '#8a9bb5', fontSize: '12px' }}>EPS</div>
                    <div style={{ color: '#e0e6ed', fontSize: '14px', fontWeight: 'bold' }}>
                        {stockInfo.eps ? `₹${stockInfo.eps.toFixed(2)}` : 'N/A'}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default StockDetails;
